import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.B9qR_F1m.js";const i="/bilder/rollen.jpg",c=JSON.parse('{"title":"Rollen, Freigaben, Phasen","description":"","frontmatter":{},"headers":[],"relativePath":"gemeinsam/rollen.md","filePath":"gemeinsam/rollen.md"}'),d={name:"gemeinsam/rollen.md"};function s(l,e,h,o,g,u){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="rollen-freigaben-phasen" tabindex="-1">Rollen, Freigaben, Phasen <a class="header-anchor" href="#rollen-freigaben-phasen" aria-label="Permalink to &quot;Rollen, Freigaben, Phasen&quot;">​</a></h1><p>Beim gemeinsamen Planen sieht und darf nicht jeder alles. Drei Dinge steuern das: die <strong>Rolle</strong> (wer bin ich), die <strong>Freigaben</strong> (was darf mein Flight ändern) und die <strong>Phase</strong> (wird gerade überhaupt geplant).</p><h2 id="rollen" tabindex="-1">Rollen <a class="header-anchor" href="#rollen" aria-label="Permalink to &quot;Rollen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rolle</th><th>Sieht</th><th>Darf</th></tr></thead><tbody><tr><td><strong>Mission Designer</strong></td><td>alles, auch verborgene Intel und das IADS</td><td>alles; speichert die .miz</td></tr><tr><td><strong>Flight Lead</strong></td><td>eigenen Flight, Intel für alle und für seinen Flight, Paket-Unterlagen</td><td>was die Freigaben für Leads erlauben</td></tr><tr><td><strong>Wingman</strong></td><td>wie der Lead</td><td>was die Freigaben für Wingmen erlauben – meist nur eigene CMDS und Farben</td></tr><tr><td><strong>Zuschauer (Übersicht)</strong></td><td>Übersicht, nur Intel für alle</td><td>nichts, nur lesen</td></tr></tbody></table><p>Die Bereiche <strong>Zeichnungen</strong> und <strong>IADS</strong> gibt es nur für den Designer.</p><h2 id="ansicht-als" tabindex="-1">Ansicht als … <a class="header-anchor" href="#ansicht-als" aria-label="Permalink to &quot;Ansicht als …&quot;">​</a></h2><p><img src="'+i+'" alt="Rollen-Menü: als Designer, Übersicht oder Flight ansehen" loading="lazy"></p><p>Oben rechts steht deine Rolle. Als Designer kannst du dort jederzeit in die Sicht eines anderen wechseln – <strong>Übersicht (Blau)</strong> oder <strong>als Flight</strong>, jeweils Lead oder Wing. Du siehst dann genau das, was dieser Pilot sehen und ändern darf. Das funktioniert auch ohne Server, ganz lokal.</p><p>Beim Zurückwechseln übernimmt Shardwing die Änderungen, die du in dieser Rolle gemacht hast – aber nur, was ihre Freigaben erlauben. So kannst du testen, ob die Freigaben passen.</p><h2 id="freigaben" tabindex="-1">Freigaben <a class="header-anchor" href="#freigaben" aria-label="Permalink to &quot;Freigaben&quot;">​</a></h2><p>Pro Flight, getrennt für Lead und Wingman, in der <a href="/bereiche/uebersicht#freigaben">Übersicht</a>:</p><table tabindex="0"><thead><tr><th>Freigabe</th><th>Bedeutet</th><th style="text-align:center;">Standard Lead</th><th style="text-align:center;">Standard Wingman</th></tr></thead><tbody><tr><td><strong>Route &amp; Steerpoints</strong></td><td>Route bzw. Steerpoints der Cartridge ändern</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td><strong>Funk-Presets</strong></td><td>COMM-Kanäle der Cartridge ändern</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td><strong>CMDS</strong></td><td>Gegenmaßnahmen-Programme – gelten nur fürs eigene Flugzeug</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><strong>Lineup Card</strong></td><td>Joker, Bingo, Hinweise, Kartenseiten</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td><strong>Eigene Threats</strong></td><td>Threats setzen, die nur der eigene Flight sieht</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr><tr><td><strong>Beladung</strong></td><td>Beladung wählen – im Rahmen der <a href="/bereiche/beladung#freigabe-fur-piloten">Freigabe für Piloten</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td></tr></tbody></table><h2 id="phasen" tabindex="-1">Phasen <a class="header-anchor" href="#phasen" aria-label="Permalink to &quot;Phasen&quot;">​</a></h2><p>Oben links in der <a href="/bereiche/uebersicht">Übersicht</a>:</p><table tabindex="0"><thead><tr><th>Phase</th><th>Flights können …</th><th>Typischer Zeitpunkt</th></tr></thead><tbody><tr><td><strong>Entwurf</strong></td><td>nur ansehen</td><td>Du bereitest noch vor.</td></tr><tr><td><strong>Planung</strong></td><td>im Rahmen ihrer Freigaben ändern</td><td>Die Sign-up-Phase läuft, Flights planen.</td></tr><tr><td><strong>Eingefroren</strong></td><td>nur ansehen</td><td>Kurz vor dem Briefing: Stand steht, Mission wird gebaut.</td></tr></tbody></table><p>Piloten sehen oben <em>Nur lesen · Entwurf</em> bzw. <em>Nur lesen · Eingefroren</em>, wenn sie gerade nichts ändern dürfen.</p><h2 id="was-keiner-sieht" tabindex="-1">Was keiner sieht <a class="header-anchor" href="#was-keiner-sieht" aria-label="Permalink to &quot;Was keiner sieht&quot;">​</a></h2><p>Intel ist streng: Ein Flight sieht nur Bedrohungen, die <strong>für alle</strong> oder <strong>für ihn</strong> freigegeben sind, und die eigenen Threats seines Flights. Der Server liefert jedem Piloten nur seine Sicht aus – auch technisch bekommt sein Browser nicht mehr zu sehen.</p>',18)])])}const m=t(d,[["render",s]]);export{c as __pageData,m as default};
